import { render } from '@solidjs/web';
import {
  createSignal,
  createMemo,
  createOptimistic,
  action,
  affects,
  refresh,
  Loading,
  isPending,
} from 'solid-js';

function createAPI() {
  let total = 0;
  return {
    async read() {
      await new Promise((resolve) => setTimeout(resolve, 80));
      return total;
    },
    async increment(fail = false) {
      await new Promise((resolve) => setTimeout(resolve, 600));
      if (fail)
        throw new Error('Save failed; the optimistic change was rolled back.');
      total += 1;
    },
  };
}

function App() {
  const api = createAPI();
  const count = createMemo(() => api.read());
  const [displayed, setDisplayed] = createOptimistic(() => count());
  const [failNext, setFailNext] = createSignal(false);
  const [error, setError] = createSignal('');
  const increment = action(function* (fail) {
    // Show the optimistic value before waiting.
    affects(count);
    yield api.increment(fail);
    yield refresh(count);
  });
  function save() {
    setError('');
    void increment(failNext()).catch((error) => setError(error.message));
  }
  return (
    <Loading fallback={<p>Loading counter...</p>}>
      <p>Displayed count: {displayed()}</p>
      <button disabled={isPending(count)} onClick={save}>
        Increment optimistically
      </button>
      <label>
        <input
          type="checkbox"
          checked={failNext()}
          onChange={(event) => setFailNext(event.currentTarget.checked)}
        />{' '}
        Fail next save
      </label>
      <p role="status">{isPending(count) ? 'Updating...' : 'Up to date'}</p>
      <p role="alert">{error()}</p>
    </Loading>
  );
}

render(() => <App />, document.getElementById('app'));

